  1→/**
  2→ * Centralized Resend email service.
  3→ *
  4→ * All send functions return `true` on success, `false` on failure — they never
  5→ * throw. This lets callers fire-and-forget without wrapping in try/catch.
  6→ */
  7→import { Resend } from "resend";
  8→
  9→// ---------------------------------------------------------------------------
 10→// Types
 11→// ---------------------------------------------------------------------------
 12→
 13→export interface EmailOptions {
 14→  /** Display name in the From field (e.g. "Cool Store"). Defaults to shop name + "via Pinzo". */
 15→  senderName?: string | null;
 16→  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
 17→  replyTo?: string | null;
 18→}
 19→
 20→// ---------------------------------------------------------------------------
 21→// Client singleton
 22→// ---------------------------------------------------------------------------
 23→
 24→let client: Resend | null = null;
 25→
 26→function getClient(): Resend | null {
 27→  if (client) return client;
 28→  const apiKey = process.env.RESEND_API_KEY;
 29→  if (!apiKey) {
 30→    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
 31→    return null;
 32→  }
 33→  client = new Resend(apiKey);
 34→  return client;
 35→}
 36→
 37→function getRawFromEmail(): string {
 38→  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
 39→}
 40→
 41→function shopDisplayName(shop: string): string {
 42→  return shop.replace(".myshopify.com", "");
 43→}
 44→
 45→/**
 46→ * Build the full From address with display name.
 47→ *
 48→ * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
 49→ * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
 50→ */
 51→function buildFrom(shop: string, options?: EmailOptions): string {
 52→  const displayName = options?.senderName?.trim() || shopDisplayName(shop);
 53→  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
 54→}
 55→
 56→/**
 57→ * Build optional reply_to field. Returns undefined when not configured
 58→ * so it can be spread into the Resend payload without adding an empty header.
 59→ */
 60→function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
 61→  const replyTo = options?.replyTo?.trim();
 62→  if (replyTo) return { reply_to: replyTo };
 63→  return {};
 64→}
 65→
 66→// ---------------------------------------------------------------------------
 67→// 1. Waitlist Confirmation  (App → Customer)
 68→// ---------------------------------------------------------------------------
 69→
 70→export async function sendWaitlistConfirmation(
 71→  to: string,
 72→  zipCode: string,
 73→  shop: string,
 74→  options?: EmailOptions,
 75→): Promise<boolean> {
 76→  const resend = getClient();
 77→  if (!resend) return false;
 78→
 79→  const name = options?.senderName?.trim() || shopDisplayName(shop);
 80→
 81→  try {
 82→    await resend.emails.send({
 83→      from: buildFrom(shop, options),
 84→      to,
 85→      subject: `You're on the waitlist — ${name}`,
 86→      html: `
 87→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
 88→          <h2 style="margin:0 0 16px">You're on the waitlist!</h2>
 89→          <p>Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
 90→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
 91→        </div>
 92→      `,
 93→      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
 94→      ...buildReplyTo(options),
 95→    });
 96→    return true;
 97→  } catch (error) {
 98→    console.error("[email] Failed to send waitlist confirmation:", error);
 99→    return false;
100→  }
101→}
102→
103→// ---------------------------------------------------------------------------
104→// 2. Merchant Alert  (App → Merchant)
105→// ---------------------------------------------------------------------------
106→
107→export async function sendMerchantWaitlistAlert(
108→  to: string,
109→  customerEmail: string,
110→  zipCode: string,
111→  shop: string,
112→  options?: EmailOptions,
113→): Promise<boolean> {
114→  const resend = getClient();
115→  if (!resend) return false;
116→
117→  const name = options?.senderName?.trim() || shopDisplayName(shop);
118→
119→  try {
120→    await resend.emails.send({
121→      from: buildFrom(shop, options),
122→      to,
123→      subject: `New waitlist signup: ${zipCode}`,
124→      html: `
125→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
126→          <h2 style="margin:0 0 16px">New waitlist signup</h2>
127→          <p>A customer just joined the waitlist for ZIP code <strong>${zipCode}</strong>.</p>
128→          <table style="margin:16px 0;border-collapse:collapse">
129→            <tr><td style="padding:4px 12px 4px 0;color:#666">Email</td><td>${customerEmail}</td></tr>
130→            <tr><td style="padding:4px 12px 4px 0;color:#666">ZIP Code</td><td>${zipCode}</td></tr>
131→          </table>
132→          <p style="color:#666;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
133→        </div>
134→      `,
135→      text: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
136→      ...buildReplyTo(options),
137→    });
138→    return true;
139→  } catch (error) {
140→    console.error("[email] Failed to send merchant waitlist alert:", error);
141→    return false;
142→  }
143→}
144→
145→// ---------------------------------------------------------------------------
146→// 3. ZIP Available Notification  (App → Customer)
147→// ---------------------------------------------------------------------------
148→
149→export async function sendZipAvailableNotification(
150→  to: string,
151→  zipCode: string,
152→  shop: string,
153→  shopUrl: string,
154→  options?: EmailOptions,
155→): Promise<boolean> {
156→  const resend = getClient();
157→  if (!resend) return false;
158→
159→  const name = options?.senderName?.trim() || shopDisplayName(shop);
160→
161→  try {
162→    await resend.emails.send({
163→      from: buildFrom(shop, options),
164→      to,
165→      subject: `Great news! We now deliver to ${zipCode}`,
166→      html: `
167→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
168→          <h2 style="margin:0 0 16px">Great news!</h2>
169→          <p>We're excited to let you know that delivery is now available to ZIP code <strong>${zipCode}</strong>.</p>
170→          <p><a href="${shopUrl}" style="display:inline-block;padding:10px 20px;background:#008060;color:#fff;text-decoration:none;border-radius:4px;margin-top:8px">Shop Now</a></p>
171→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
172→        </div>
173→      `,
174→      text: `Great news!\n\nDelivery is now available to ZIP code ${zipCode}. Visit ${shopUrl} to place your order.\n\n— ${name}`,
175→      ...buildReplyTo(options),
176→    });
177→    return true;
178→  } catch (error) {
179→    console.error("[email] Failed to send ZIP available notification:", error);
180→    return false;
181→  }
182→}
183→
184→// ---------------------------------------------------------------------------
185→// 4. Test Email  (Settings page)
186→// ---------------------------------------------------------------------------
187→
188→export async function sendTestEmail(
189→  to: string,
190→  options?: EmailOptions,
191→  shop?: string,
192→): Promise<boolean> {
193→  const resend = getClient();
194→  if (!resend) return false;
195→
196→  const name = options?.senderName?.trim() || (shop ? shopDisplayName(shop) : "Your Store");
197→
198→  try {
199→    await resend.emails.send({
200→      from: buildFrom(shop || "test-store.myshopify.com", options),
201→      to,
202→      subject: "Pinzo — Test Email",
203→      html: `
204→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
205→          <h2 style="margin:0 0 16px">Test email received!</h2>
206→          <p>Your email integration is working correctly.</p>
207→          <p style="margin-top:16px"><strong>From:</strong> ${name} via Pinzo &lt;${getRawFromEmail()}&gt;</p>
208→          ${options?.replyTo ? `<p><strong>Reply-To:</strong> ${options.replyTo}</p>` : "<p><strong>Reply-To:</strong> <em>Not set</em></p>"}
209→          <p style="color:#666;font-size:13px;margin-top:24px">You will receive notifications when customers join your waitlist.</p>
210→        </div>
211→      `,
212→      text: `Test email received!\n\nYour email integration is working correctly.\n\nFrom: ${name} via Pinzo <${getRawFromEmail()}>\nReply-To: ${options?.replyTo || "Not set"}\n\nYou will receive notifications when customers join your waitlist.`,
213→      ...buildReplyTo(options),
214→    });
215→    return true;
216→  } catch (error) {
217→    console.error("[email] Failed to send test email:", error);
218→    return false;
219→  }
220→}
