 32→// ---------------------------------------------------------------------------
 33→// Loader
 34→// ---------------------------------------------------------------------------
 35→
 36→export const loader = async ({ request }: LoaderFunctionArgs) => {
 37→  const { session, admin } = await authenticate.admin(request);
 38→  const shop = session.shop;
 39→
 40→  const [subscription, zipCount, shopSettings, shopResponse] = await Promise.all([
 41→    getShopSubscription(shop),
 42→    db.zipCode.count({ where: { shop } }),
 43→    db.shopSettings.findUnique({ where: { shop } }),
 44→    admin.graphql(`{ shop { name } }`),
 45→  ]);
 46→
 47→  const shopData = await shopResponse.json();
 48→  const shopName: string = shopData.data?.shop?.name ?? shop.replace(".myshopify.com", "");
 49→
 50→  // Cache the shop display name so email service can use it without API calls
 51→  await db.shopSettings.upsert({
 52→    where: { shop },
 53→    create: { shop, shopName },
 54→    update: { shopName },
 55→  });
 56→
 57→  return {
 58→    subscription,
 59→    zipCount,
 60→    shop,
 61→    shopName,
 62→    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
 63→    notificationEmail: shopSettings?.notificationEmail ?? "",
 64→    emailSenderName: shopSettings?.emailSenderName ?? "",
 65→    emailReplyTo: shopSettings?.emailReplyTo ?? "",
 66→  };
 67→};
 68→
 69→// ---------------------------------------------------------------------------
 70→// Action
 71→// ---------------------------------------------------------------------------
 72→
 73→export const action = async ({ request }: ActionFunctionArgs) => {
 74→  const { session } = await authenticate.admin(request);
 75→  const shop = session.shop;
 76→
 77→  const formData = await request.formData();
 78→  const intent = formData.get("intent") as string;
 79→
 80→  try {
 81→    if (intent === "save-behavior") {
 82→      const defaultBehavior = formData.get("defaultBehavior") as string;
 83→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 84→        return { error: "Invalid value for defaultBehavior" };
 85→      }
 86→      await db.shopSettings.upsert({
 87→        where: { shop },
 88→        create: { shop, defaultBehavior },
 89→        update: { defaultBehavior },
 90→      });
 91→      return { success: true, intent };
 92→    }
 93→
 94→    if (intent === "save-notification") {
 95→      const notificationEmail =
 96→        (formData.get("notificationEmail") as string | null) ?? "";
 97→      await db.shopSettings.upsert({
 98→        where: { shop },
 99→        create: { shop, notificationEmail: notificationEmail || null },
100→        update: { notificationEmail: notificationEmail || null },
101→      });
102→      return { success: true, intent };
103→    }
104→
105→    if (intent === "save-email-settings") {
106→      const emailSenderName =
107→        (formData.get("emailSenderName") as string | null)?.trim() || null;
108→      const emailReplyTo =
109→        (formData.get("emailReplyTo") as string | null)?.trim() || null;
110→      await db.shopSettings.upsert({
111→        where: { shop },
112→        create: { shop, emailSenderName, emailReplyTo },
113→        update: { emailSenderName, emailReplyTo },
114→      });
115→      return { success: true, intent };
116→    }
117→
118→    if (intent === "send-test-email") {
119→      const testEmail = (formData.get("testEmail") as string | null) ?? "";
120→      if (!testEmail) return { error: "No email address provided." };
121→      const settings = await db.shopSettings.findUnique({ where: { shop } });
122→      const sent = await sendTestEmail(
123→        testEmail,
124→        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
125→        shop,
126→      );
127→      return sent
128→        ? { success: true, intent }
129→        : { error: "Failed to send test email. Check your Resend API key and sender email." };
130→    }
131→
132→    return { error: "Unknown intent" };
133→  } catch {
134→    return { error: "Failed to save settings. Please try again." };
135→  }
136→};
