// Shared plan constants — safe for both client and server

/**
 * Sentinel value used in place of Infinity for "unlimited" plan limits.
 * Infinity cannot be serialized to JSON (becomes null), so we use this
 * large number as the canonical "no limit" value. All limit comparisons
 * should use isUnlimited() or compare against UNLIMITED.
 */
export const UNLIMITED = 999999;

export const PLAN_FREE = "free";
export const PLAN_STARTER_MONTHLY = "Starter Monthly";
export const PLAN_STARTER_ANNUAL = "Starter Annual";
export const PLAN_PRO_MONTHLY = "Pro Monthly";
export const PLAN_PRO_ANNUAL = "Pro Annual";
export const PLAN_ULTIMATE_MONTHLY = "Ultimate Monthly";
export const PLAN_ULTIMATE_ANNUAL = "Ultimate Annual";

export const ALL_PAID_PLANS = [
  PLAN_STARTER_MONTHLY,
  PLAN_STARTER_ANNUAL,
  PLAN_PRO_MONTHLY,
  PLAN_PRO_ANNUAL,
  PLAN_ULTIMATE_MONTHLY,
  PLAN_ULTIMATE_ANNUAL,
];

export type PlanTier = "free" | "starter" | "pro" | "ultimate";

export interface PlanLimits {
  maxZipCodes: number;
  allowBlocked: boolean;
  maxDeliveryRules: number;
  maxWaitlist: number;
  csvImport: boolean;
  csvExport: boolean;
  widgetFullCustom: boolean;
  showEtaCodReturn: boolean;
  cartBlocking: boolean;
  customCss: boolean;
  apiAccess: boolean;
  label: string;
}

export const PLAN_LIMITS: Record<PlanTier, PlanLimits> = {
  free: {
    maxZipCodes: 20,
    allowBlocked: false,
    maxDeliveryRules: 0,
    maxWaitlist: 0,
    csvImport: false,
    csvExport: false,
    widgetFullCustom: false,
    showEtaCodReturn: false,
    cartBlocking: false,
    customCss: false,
    apiAccess: false,
    label: "Free",
  },
  starter: {
    maxZipCodes: 500,
    allowBlocked: false,
    maxDeliveryRules: 3,
    maxWaitlist: 25,
    csvImport: true,
    csvExport: false,
    widgetFullCustom: true,
    showEtaCodReturn: true,
    cartBlocking: false,
    customCss: false,
    apiAccess: false,
    label: "Starter",
  },
  pro: {
    maxZipCodes: UNLIMITED,
    allowBlocked: true,
    maxDeliveryRules: UNLIMITED,
    maxWaitlist: UNLIMITED,
    csvImport: true,
    csvExport: true,
    widgetFullCustom: true,
    showEtaCodReturn: true,
    cartBlocking: true,
    customCss: false,
    apiAccess: false,
    label: "Pro",
  },
  ultimate: {
    maxZipCodes: UNLIMITED,
    allowBlocked: true,
    maxDeliveryRules: UNLIMITED,
    maxWaitlist: UNLIMITED,
    csvImport: true,
    csvExport: true,
    widgetFullCustom: true,
    showEtaCodReturn: true,
    cartBlocking: true,
    customCss: true,
    apiAccess: true,
    label: "Ultimate",
  },
};

export function getPlanTier(planName: string): PlanTier {
  if (planName === PLAN_STARTER_MONTHLY || planName === PLAN_STARTER_ANNUAL)
    return "starter";
  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
    return "pro";
  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
    return "ultimate";
  return "free";
}

/**
 * Public API endpoint — serves widget configuration for the storefront block.
 *
 * Called from the theme app extension block JS to get the merchant's
 * widget styling and text settings.
 *
 * GET /api/widget-config?shop=store.myshopify.com
 *
 * Response: WidgetConfig JSON (falls back to defaults if no config found)
 */
import type { LoaderFunctionArgs } from "react-router";
import db from "../db.server";
import { getShopSubscription } from "../billing.server";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Content-Type": "application/json",
};

const DEFAULTS = {
  position: "inline",
  primaryColor: "#008060",
  successColor: "#008060",
  errorColor: "#D72C0D",
  backgroundColor: "#FFFFFF",
  textColor: "#202223",
  heading: "Check Delivery Availability",
  placeholder: "Enter your zip code",
  buttonText: "Check",
  successMessage: "Great news! We deliver to your area.",
  errorMessage: "Sorry, we don't deliver to this area yet.",
  notFoundMessage: "We currently do not ship to this ZIP code.",
  showEta: true,
  showZone: false,
  showWaitlistOnFailure: false,
  showCod: true,
  showReturnPolicy: true,
  showCutoffTime: true,
  showDeliveryDays: true,
  showDeliveryDate: true,
  showCountdown: true,
  showDeliveryFee: true,
  blockCartOnInvalid: false,
  blockCheckoutInCart: false,
  showSocialProof: true,
  lockButtonsUntilZipCheck: true,
  borderRadius: "8",
  customCss: null as string | null,
};

/**
 * Sanitize merchant-supplied custom CSS before embedding it in a storefront
 * <style> element. Strips known injection vectors:
 *   - </style> close tags  — would break out of the enclosing style block
 *   - @import directives   — would load arbitrary external stylesheets
 *   - expression()         — IE-era JS-in-CSS execution vector
 *   - javascript: URLs     — covers url(javascript:...) and similar
 */
function sanitizeCss(css: string): string {
  return css
    // Break out of <style> blocks — strip both opening and closing tags
    .replace(/<style\b[^>]*>/gi, "")
    .replace(/<\/style>/gi, "")
    // External stylesheet loading
    .replace(/@import\b[^;]*(;|$)/gi, "")
    // IE expression() — JS execution inside CSS property values
    .replace(/\bexpression\s*\(/gi, "")
    // javascript: protocol inside url() references
    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
    // data: URIs inside url() — can embed arbitrary content including scripts
