      {/* Error / Not Found result — matches storefront rendering */}
      {(previewState === "error" || previewState === "notfound") && (
        <>
          <div className="zcc-result fail">
            <div className="zcc-result-icon">{xCircleIcon}</div>
            <div className="zcc-result-content">
